var result = JSON.parse($input.first().json.output);

const text = $('Gmail Trigger').first().json.From;
const matches = text.match(/<([^>]+)>/g);

// Matches will be: ["<test>", "<content>"]
// To remove the brackets:
const res = matches.map(m => m.replace(/<|>/g, ''));

result.email = res[0];

return [{ json: result }];

const data = $('Code in JavaScript').first().json;

function encode(value) {
  return encodeURIComponent(value || "");
}

// Convert product array to readable string
const products = (data.products || []).map(p => {
  return `${p.quantity || ""} ${p.product || ""} ${p.specifications || ""}`.trim();
}).join(", ");

const baseUrl = "https://docs.google.com/forms/d/e/1FAIpQLSfRZFVuyUCLGgCCNGWL8bQQ191Wkuw7cwgIwGnpnqSjoc2RkA/viewform?usp=pp_url";

const params = [
  "entry.958235835=" + encode($input.first().json.quote_id),
  "entry.350650412=" + encode(data.customer_name),
  "entry.1527956893=" + encode(data.company_name),
  "entry.521148709=" + encode(products),
  "entry.1315103597=" + encode(data.delivery_date),
  "entry.1775243247=" + encode(data.delivery_location)
];

return [{
  json: {
    form_url: baseUrl + "&" + params.join("&")
  }
}];

return [{
