var items = []
for (const item of $input.all()) {
  const prod = item.json.product.toLocaleLowerCase().trim();
  if(prod == $('Edit Fields1').first().json.product) {
    items.push(item)
  }
}

return items;

const quantity = Number($('Edit Fields1').first().json.quantity || 0);
const cost = Number($input.first().json.price || 0);

const margin = 0.2;

const selling_price_per_unit = Math.round(cost * (1 + margin));
const total_price = selling_price_per_unit * quantity;

return [
  {
    json: {
      product: $input.first().json.product,
      quantity: $('Edit Fields1').first().json.quantity,
      supplier_name: $input.first().json.supplier_name,
      cost: cost,
      selling_price_per_unit: selling_price_per_unit,
      total_price: total_price
    }
  }
];

const quoted_products = $input.all().map(item => item.json);

const grand_total = quoted_products.reduce((sum, product) => {
  return sum + Number(product.total_price || 0);
}, 0);

return [
  {
    json: {
      quote_id: $('Code in JavaScript3').first().json.quote_id,
      customer_name: $('Code in JavaScript3').first().json.customer_name,
      email: $('Google Sheets Trigger').first().json["Email Address"] ,
      company_name: $('Code in JavaScript3').first().json.company_name,
      delivery_location: $('Code in JavaScript3').first().json.delivery_location,
      delivery_date: $('Code in JavaScript3').first().json.delivery_date,
      quoted_products,
      grand_total
    }
  }
];

