const customer = ($('Code in JavaScript6').first().json.company_name || "Customer")
  .replace(/\s+/g, "_");

const today = new Date();

const day = String(today.getDate()).padStart(2, "0");
const month = String(today.getMonth() + 1).padStart(2, "0");
const year = today.getFullYear();

const formattedDate = `${day}-${month}-${year}`;

const fileName = `${customer}_${formattedDate}.pdf`;

return {fileName};

let html = $json.output;

// Remove markdown wrappers
html = html.replace(/```html/g, '');
html = html.replace(/```/g, '');

// Add clean body styling
html = html.replace(
  '<body>',
  `<body style="font-family: Arial, sans-serif; color: #333; line-height: 1.5; text-align: left; padding: 20px;">`
);

// Style unordered lists
html = html.replaceAll(
  '<ul>',
  '<ul style="padding-left: 20px; margin-top: 5px;">'
);

// Style headings
html = html.replaceAll(
  '<h3>',
  '<h3 style="margin-top: 20px; color: #222;">'
);

return [
  {
    json: {
      formatted_html: html
    }
  }
];
